<script lang="ts">
	import { get } from 'svelte/store';
	import { io } from 'socket.io-client';
	import { spring } from 'svelte/motion';

	let loadingProgress = spring(0, {
		stiffness: 0.05
	});

	import { onMount, tick, setContext } from 'svelte';
	import {
		config,
		user,
		settings,
		theme,
		WEBUI_NAME,
		mobile,
		socket,
		activeUserIds,
		USAGE_POOL,
		chatId,
		chats,
		currentChatPage,
		tags,
		temporaryChatEnabled,
		isLastActiveTab,
		isApp,
		appInfo,
		toolServers
	} from '$lib/stores';
	import { goto } from '$app/navigation';
	import { page } from '$app/state';
	import { Toaster, toast } from 'svelte-sonner';

	import { executeToolServer, getBackendConfig } from '$lib/apis';
	import { getSessionUser, terminateSession, installUnauthorizedInterceptor } from '$lib/apis/auths';

	import '../tailwind.css';
	import '../app.css';

	import 'tippy.js/dist/tippy.css';

	import { WEBUI_BASE_URL, WEBUI_HOSTNAME } from '$lib/constants';
	import i18n, { initI18n, getLanguages, changeLanguage } from '$lib/i18n';
	import { bestMatchingLanguage } from '$lib/utils';
	import { getAllTags, getChatList, updateChatEntryInList } from '$lib/apis/chats';
	import NotificationToast from '$lib/components/NotificationToast.svelte';
	import AppSidebar from '$lib/components/app/AppSidebar.svelte';
	import Skeleton from '$lib/components/common/Skeleton.svelte';
	import { chatCompletion } from '$lib/apis/openai';
	/**
	 * @typedef {Object} Props
	 * @property {import('svelte').Snippet} [children]
	 */

	/** @type {Props} */
	let { children } = $props();

	setContext('i18n', i18n);

	const bc = new BroadcastChannel('active-tab-channel');

	let loaded = $state(false);

	const BREAKPOINT = 768;

	const setupSocket = async (enableWebsocket) => {
		const _socket = io(`${WEBUI_BASE_URL}` || undefined, {
			reconnection: true,
			reconnectionDelay: 1000,
			reconnectionDelayMax: 5000,
			randomizationFactor: 0.5,
			path: '/ws/socket.io',
			transports: enableWebsocket ? ['websocket'] : ['polling', 'websocket'],
			auth: { token: localStorage.token }
		});

		await socket.set(_socket);

		_socket.on('connect_error', (err) => {
			console.log('connect_error', err);
		});

		_socket.on('connect', () => {
			console.log('connected', _socket.id);
		});

		_socket.on('reconnect_attempt', (attempt) => {
			console.log('reconnect_attempt', attempt);
		});

		_socket.on('reconnect_failed', () => {
			console.log('reconnect_failed');
		});

		_socket.on('disconnect', (reason, details) => {
			console.log(`Socket ${_socket.id} disconnected due to ${reason}`);
			if (details) {
				console.log('Additional details:', details);
			}
		});

		_socket.on('user-list', (data) => {
			console.log('user-list', data);
			activeUserIds.set(data.user_ids);
		});

		_socket.on('usage', (data) => {
			console.log('usage', data);
			USAGE_POOL.set(data['models']);
		});
	};

	const executeTool = async (data, cb) => {
		const toolServer = get(toolServers)?.find((server) => server.url === data.server?.url);

		console.log('executeTool', data, toolServer);

		if (toolServer) {
			const res = await executeToolServer(
				toolServer.key,
				toolServer.url,
				data?.name,
				data?.params,
				toolServer
			);

			console.log('executeToolServer', res);
			if (cb) {
				cb(JSON.parse(JSON.stringify(res)));
			}
		} else {
			if (cb) {
				cb(
					JSON.parse(
						JSON.stringify({
							error: 'Tool Server Not Found'
						})
					)
				);
			}
		}
	};

	const chatEventHandler = async (event: any, cb: any) => {
		const chat = page.url.pathname.includes(`/c/${event.chat_id}`);

		let isFocused = document.visibilityState !== 'visible';
		if (window.electronAPI) {
			const res = await window.electronAPI.send({
				type: 'window:isFocused'
			});
			if (res) {
				isFocused = res.isFocused;
			}
		}

		await tick();
		const type = event?.data?.type ?? null;
		const data = event?.data?.data ?? null;

		if ((event.chat_id !== get(chatId) && !get(temporaryChatEnabled)) || isFocused) {
			if (type === 'chat:completion') {
				const { done, content, title } = data;

				if (done) {
					if (get(isLastActiveTab)) {
						if (get(settings)?.notificationEnabled ?? false) {
							new Notification(`${title} | BCGPT`, {
								body: content,
								icon: `/static/favicon.png`
							});
						}
					}

					toast.custom(NotificationToast, {
						componentProps: {
							onClick: () => {
								goto(`/c/${event.chat_id}`);
							},
							content: content,
							title: title
						},
						duration: 15000,
						unstyled: true
					});
				}
			} else if (type === 'chat:title') {
				chats.set(updateChatEntryInList(get(chats), event.chat_id, { title: data, updated_at: Date.now() / 1000 }));
			} else if (type === 'chat:tags') {
				tags.set(await getAllTags(localStorage.token));
			}
		} else if (data?.session_id === get(socket).id) {
			if (type === 'execute:tool') {
				console.log('execute:tool', data);
				executeTool(data, cb);
			} else if (type === 'request:chat:completion') {
				console.log(data, get(socket).id);
				const { session_id, channel, form_data, model } = data;

				try {
					const directConnections = get(settings)?.directConnections ?? {};

					if (directConnections) {
						const urlIdx = model?.urlIdx;

						const OPENAI_API_URL = directConnections.OPENAI_API_BASE_URLS[urlIdx];
						const OPENAI_API_KEY = directConnections.OPENAI_API_KEYS[urlIdx];
						const API_CONFIG = directConnections.OPENAI_API_CONFIGS[urlIdx];

						try {
							if (API_CONFIG?.prefix_id) {
								const prefixId = API_CONFIG.prefix_id;
								form_data['model'] = form_data['model'].replace(`${prefixId}.`, ``);
							}

							const [res, controller] = await chatCompletion(
								OPENAI_API_KEY,
								form_data,
								OPENAI_API_URL
							);

							if (res) {
								// raise if the response is not ok
								if (!res.ok) {
									throw await res.json();
								}

								if (form_data?.stream ?? false) {
									cb({
										status: true
									});
									console.log({ status: true });

									// res will either be SSE or JSON
									const reader = res.body.getReader();
									const decoder = new TextDecoder();

									const processStream = async () => {
										while (true) {
											// Read data chunks from the response stream
											const { done, value } = await reader.read();
											if (done) {
												break;
											}

											// Decode the received chunk
											const chunk = decoder.decode(value, { stream: true });

											// Process lines within the chunk
											const lines = chunk.split('\n').filter((line) => line.trim() !== '');

											for (const line of lines) {
												console.log(line);
												get(socket)?.emit(channel, line);
											}
										}
									};

									// Process the stream in the background
									await processStream();
								} else {
									const data = await res.json();
									cb(data);
								}
							} else {
								throw new Error('An error occurred while fetching the completion');
							}
						} catch (error) {
							console.error('chatCompletion', error);
							cb(error);
						}
					}
				} catch (error) {
					console.error('chatCompletion', error);
					cb(error);
				} finally {
					get(socket).emit(channel, {
						done: true
					});
				}
			} else {
				console.log('chatEventHandler', event);
			}
		}
	};

	const channelEventHandler = async (event: any) => {
		if (event.data?.type === 'typing') {
			return;
		}

		// check url path
		const channel = page.url.pathname.includes(`/channels/${event.channel_id}`);

		let isFocused = document.visibilityState !== 'visible';
		if (window.electronAPI) {
			const res = await window.electronAPI.send({
				type: 'window:isFocused'
			});
			if (res) {
				isFocused = res.isFocused;
			}
		}

		if ((!channel || isFocused) && event?.user?.id !== get(user)?.id) {
			await tick();
			const type = event?.data?.type ?? null;
			const data = event?.data?.data ?? null;

			if (type === 'message') {
				if (get(isLastActiveTab)) {
					if (get(settings)?.notificationEnabled ?? false) {
						new Notification(`${data?.user?.name} (#${event?.channel?.name}) | BCGPT`, {
							body: data?.content,
							icon: data?.user?.profile_image_url ?? `/static/favicon.png`
						});
					}
				}

				toast.custom(NotificationToast, {
					componentProps: {
						onClick: () => {
							goto(`/channels/${event.channel_id}`);
						},
						content: data?.content,
						title: event?.channel?.name
					},
					duration: 15000,
					unstyled: true
				});
			}
		}
	};

	onMount(async () => {
		installUnauthorizedInterceptor();
		window.addBootLog?.('Initializing runtime...', 'loading');

		if (typeof window !== 'undefined' && window.applyTheme) {
			window.applyTheme();
		}

		if (window?.electronAPI) {
			const info = await window.electronAPI.send({
				type: 'app:info'
			});

			if (info) {
				isApp.set(true);
				appInfo.set(info);

				const data = await window.electronAPI.send({
					type: 'app:data'
				});

				if (data) {
					appData.set(data);
				}
			}
		}

		// Listen for messages on the BroadcastChannel
		bc.onmessage = (event) => {
			if (event.data === 'active') {
				isLastActiveTab.set(false); // Another tab became active
			}
		};

		// Set yourself as the last active tab when this tab is focused
		const handleVisibilityChange = () => {
			if (document.visibilityState === 'visible') {
				isLastActiveTab.set(true); // This tab is now the active tab
				bc.postMessage('active'); // Notify other tabs that this tab is active
			}
		};

		// Add event listener for visibility state changes
		document.addEventListener('visibilitychange', handleVisibilityChange);

		// Call visibility change handler initially to set state on load
		handleVisibilityChange();

		theme.set(localStorage.theme);

		mobile.set(window.innerWidth < BREAKPOINT);

		const onResize = () => {
			if (window.innerWidth < BREAKPOINT) {
				mobile.set(true);
			} else {
				mobile.set(false);
			}
		};
		window.addEventListener('resize', onResize);

		user.subscribe((value) => {
			if (value) {
				get(socket)?.off('chat-events', chatEventHandler);
				get(socket)?.off('channel-events', channelEventHandler);

				get(socket)?.on('chat-events', chatEventHandler);
				get(socket)?.on('channel-events', channelEventHandler);
			} else {
				get(socket)?.off('chat-events', chatEventHandler);
				get(socket)?.off('channel-events', channelEventHandler);
			}
		});

		window.addBootLog?.('Fetching backend config...', 'loading');
		let backendConfig = null;
		try {
			const configController = new AbortController();
			const configTimeout = setTimeout(() => configController.abort(), 10000);
			backendConfig = await getBackendConfig(configController.signal);
			clearTimeout(configTimeout);
			window.addBootLog?.('Backend config loaded', 'done');
		} catch (error) {
			const errMsg =
				error?.name === 'AbortError'
					? 'Server response timed out (10s). Please make sure the backend server is running.'
					: `Backend connection failed: ${error?.message || error}`;
			window.addBootLog?.(errMsg, 'error');
			console.error('Error loading backend config:', error);
		}

		initI18n(localStorage?.locale);
		window.addBootLog?.('Initializing i18n...', 'loading');
		if (!localStorage.locale) {
			try {
				const languages = await getLanguages();
				const browserLanguages = navigator.languages
					? navigator.languages
					: [navigator.language || navigator.userLanguage];
				const lang = backendConfig?.default_locale
					? backendConfig.default_locale
					: bestMatchingLanguage(languages, browserLanguages, 'en-US');
				changeLanguage(lang);
			} catch (error) {
				console.error('Error initializing language:', error);
			}
		}
		window.addBootLog?.('i18n ready', 'done');

		if (backendConfig) {
			// Save Backend Status to Store
			await config.set(backendConfig);
			await WEBUI_NAME.set(backendConfig.name);

			if (get(config)) {
				window.addBootLog?.('Connecting websocket...', 'loading');
				await setupSocket(get(config).features?.enable_websocket ?? true);
				window.addBootLog?.('WebSocket connected', 'done');

				const currentUrl = `${window.location.pathname}${window.location.search}`;
				const encodedUrl = encodeURIComponent(currentUrl);

				if (localStorage.token) {
					// Get Session User Info
					window.addBootLog?.('Authenticating session...', 'loading');
					const sessionUser = await getSessionUser(localStorage.token).catch((error) => {
						toast.error(`${error}`);
						return null;
					});

					if (sessionUser) {
						// Save Session User to Store
						get(socket).emit('user-join', { auth: { token: sessionUser.token } });

						await user.set(sessionUser);
						await config.set(await getBackendConfig());
						window.addBootLog?.('Session authenticated', 'done');
					} else {
						window.addBootLog?.('Session expired, redirecting...', 'error');
						await terminateSession({ redirect: false });
						await goto(`/auth?redirect=${encodedUrl}`);
					}
				} else {
					// Don't redirect if we're already on the auth page
					// Needed because we pass in tokens from OAuth logins via URL fragments
					if (page.url.pathname !== '/auth') {
						await goto(`/auth?redirect=${encodedUrl}`);
					}
				}
			}
		} else {
			// Redirect to /error when Backend Not Detected
			window.bootFailed?.(
				$i18n.t('Cannot connect to the backend server'),
				$i18n.t(
					'Backend server is not responding.\n' +
						' - Docker: check container status with docker ps\n' +
						' - Local: verify bcgpt serve or npm run dev is running'
				)
			);
			await goto(`/error`);
		}

		window.addBootLog?.('Boot complete', 'done');

		await tick();

		if (
			document.documentElement.classList.contains('her') &&
			document.getElementById('progress-bar')
		) {
			loadingProgress.subscribe((value) => {
				const progressBar = document.getElementById('progress-bar');

				if (progressBar) {
					progressBar.style.width = `${value}%`;
				}
			});

			await loadingProgress.set(100);

			document.getElementById('splash-screen')?.remove();

			const audio = new Audio(`/audio/greeting.mp3`);
			const playAudio = () => {
				audio.play();
				document.removeEventListener('click', playAudio);
			};

			document.addEventListener('click', playAudio);

			loaded = true;
		} else {
			document.getElementById('splash-screen')?.remove();
			loaded = true;
		}

		return () => {
			window.removeEventListener('resize', onResize);
			bc.close();
		};
	});
</script>

<svelte:head>
	<title>{$WEBUI_NAME}</title>
	<link crossorigin="anonymous" rel="icon" href="{$config?.logo_url ? WEBUI_BASE_URL + $config.logo_url : WEBUI_BASE_URL + '/static/favicon.png'}" />
	<link crossorigin="anonymous" rel="shortcut icon" href="{$config?.logo_url ? WEBUI_BASE_URL + $config.logo_url : WEBUI_BASE_URL + '/static/favicon.ico'}" />

	<!-- rosepine themes have been disabled as it's not up to date with our latest version. -->
	<!-- feel free to make a PR to fix if anyone wants to see it return -->
	<!-- <link rel="stylesheet" type="text/css" href="/themes/rosepine.css" />
	<link rel="stylesheet" type="text/css" href="/themes/rosepine-dawn.css" /> -->
</svelte:head>

{#if loaded}
	{#if $isApp}
		<div class="flex flex-row h-screen">
			<AppSidebar />

			<div class="w-full flex-1 max-w-[calc(100%-4.5rem)]">
				{@render children?.()}
			</div>
		</div>
	{:else}
		{@render children?.()}
	{/if}
{:else}
	<div class="flex flex-row h-screen w-full">
		<!-- Sidebar skeleton -->
		<div class="min-w-[4.5rem] bg-gray-50 dark:bg-gray-950 flex gap-2.5 flex-col pt-8 items-center">
			<Skeleton variant="circle" width="2.75rem" />
			<div class="w-10 border-t border-gray-100 dark:border-gray-900"></div>
			{#each Array(5) as _}
				<Skeleton variant="circle" width="2.75rem" />
			{/each}
		</div>

		<!-- Main content skeleton -->
		<div class="flex-1 flex flex-col h-full">
			<!-- Header skeleton -->
			<div class="flex items-center justify-between px-4 py-3 border-b border-gray-100 dark:border-gray-850">
				<Skeleton width="8rem" height="1.5rem" />
				<div class="flex gap-3">
					<Skeleton variant="circle" width="2rem" />
					<Skeleton variant="circle" width="2rem" />
				</div>
			</div>

			<!-- Content area skeleton -->
			<div class="flex-1 flex flex-col items-center justify-center gap-4 p-6">
				<Skeleton width="12rem" height="2rem" />
				<Skeleton width="20rem" height="1rem" />
				<Skeleton width="16rem" height="1rem" />

				<div class="flex gap-3 mt-6">
					{#each Array(3) as _}
						<div class="w-40 h-24">
							<Skeleton variant="rect" width="100%" height="100%" />
						</div>
					{/each}
				</div>
			</div>
		</div>
	</div>
{/if}

<Toaster
	theme={$theme.includes('dark')
		? 'dark'
		: $theme === 'system'
			? window.matchMedia('(prefers-color-scheme: dark)').matches
				? 'dark'
				: 'light'
			: 'light'}
	richColors
	position="top-right"
/>
