<script lang="ts">
	interface Props {
		width?: string;
		height?: string;
		variant?: 'text' | 'circle' | 'rect';
		count?: number;
	}

	let {
		width = '100%',
		height = '1rem',
		variant = 'text',
		count = 1
	}: Props = $props();

	let baseClasses =
		$derived(variant === 'circle'
			? 'rounded-full'
			: variant === 'rect'
				? 'rounded-lg'
				: 'rounded');

	let style = $derived(variant === 'circle'
		? `width: ${width}; height: ${width};`
		: `width: ${width}; height: ${height};`);
</script>

{#each Array(count) as _}
	<div
		class="bg-gray-200 dark:bg-gray-800 animate-pulse {baseClasses}"
		{style}
		aria-hidden="true"
	></div>
{/each}
